function esc(s){return String(s==null?'':s).replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})}
function bar(v,scale){var w=Math.max(2,Math.min(100,100*v/scale));return '<span class="bar"><span style="width:'+w+'%"></span></span>'}
function card(h){
  var last=(LAST[h.id]||[]).map(function(r){return '<tr><td>'+r[0]+'</td><td>'+esc(r[1])+'</td><td>'+(r[2]==='g'?'galopp':(r[2]==0?'opl.':r[2]))+'</td><td>'+esc(r[3])+'</td><td>'+esc(r[4])+'</td><td>'+(r[5]||'')+'</td><td>'+(r[6]||'')+'</td></tr>'}).join('');
  var marks=(MARK[h.n.toLowerCase()]||[]).map(function(m){return '<span class="tag">'+esc(m)+'</span>'}).join(' ');
  var next=NEXT[h.id]?'<p><b>Nästa start:</b> '+esc(NEXT[h.id])+'</p>':'';
  return '<div class="hcard"><h2>'+esc(h.n)+' '+marks+'</h2>'+
   '<div class="facts"><div>Ålder: <b>'+(h.age||'?')+'</b></div><div>Kön: <b>'+esc(h.sex)+'</b></div>'+
   '<div>Starter (2 år): <b>'+h.st+'</b></div><div>Segrar: <b>'+h.w+'</b> ('+Math.round(100*h.w/h.st)+' %)</div>'+
   '<div>Topp 3: <b>'+h.t3+'</b></div><div>Galopper: <b>'+h.g+'</b> ('+Math.round(100*h.g/h.st)+' %)</div>'+
   '<div>Form: <b>'+(h.form==null?'–':h.form)+'</b></div><div>Styrka: <b>'+(h.elo==null?'–':h.elo)+'</b></div>'+
   '<div>Klass (förstapris, tkr): <b>'+(h.cls==null?'–':h.cls)+'</b></div><div>Bästa km-tid: <b>'+esc(h.best)+'</b></div>'+
   '<div>Senaste 5: <b>'+esc(h.r5)+'</b></div><div>Senast: <b>'+esc(h.last)+'</b></div></div>'+next+
   (last?'<table><tr><th>Datum</th><th>Bana</th><th>Plac.</th><th>Km-tid</th><th>Odds</th><th>Spår</th><th>Dist.</th></tr>'+last+'</table>':'')+'</div>';
}
function showHorse(id){var h=REG[id];if(!h)return;var box=document.getElementById('hcard');box.innerHTML=card(h);box.scrollIntoView({behavior:'smooth',block:'start'})}
